@builtin
def __truediv__(self, other, _builder=None):
    other = _unwrap_if_constexpr(other)
    return semantic.truediv(self, other, _builder)

@builtin
def __mod__(self, other, _builder=None):
    other = _unwrap_if_constexpr(other)
